function cost(weightG, express) {
  // Cost in cents: base 500; +100 per FULL 1000g over the first 1000g;
  // doubled when express.
  let total = 500;
  if (weightG > 1000) {
    total += Math.floor((weightG - 1000) / 1000) * 100;
  }
  if (express) {
    total *= 2;
  }
  return total;
}

module.exports = { cost };

