const test = require('node:test');
const assert = require('node:assert');
const { cost } = require('./shipping.js');

test('base under one kilo', () => {
  assert.strictEqual(cost(500, false), 500);
});

test('one extra-kilo surcharge', () => {
  // 2500g -> 1 full kg over 1000g -> 500 + 100 = 600
  assert.strictEqual(cost(2500, false), 600);
});

test('two extra-kilo surcharges', () => {
  // 3000g -> 2 full kg over 1000g -> 500 + 200 = 700
  assert.strictEqual(cost(3000, false), 700);
});

test('express doubles the total', () => {
  assert.strictEqual(cost(500, true), 1000);
});

