const test = require('node:test');
const assert = require('node:assert');
const { cost } = require('./shipping.js');

test('returns a number', () => {
  assert.strictEqual(typeof cost(500, false), 'number');
});

test('positive', () => {
  assert.ok(cost(2500, false) > 0);
});

test('express not cheaper', () => {
  assert.ok(cost(500, true) >= cost(500, false));
});

test('heavier not cheaper', () => {
  assert.ok(cost(3000, false) >= cost(500, false));
});
